import createClient, { type Middleware } from "openapi-fetch";
import { auth } from "@/lib/firebase";
// Generated by `npm run gen:api` from ./openapi.json (see api/scripts/export_openapi.py).
import type { paths } from "./schema";

export const api = createClient<paths>({ baseUrl: import.meta.env.VITE_API_BASE_URL ?? "" });

/** Sends the signed-in person's Firebase ID token; signs them out if the API rejects it. */
export const authMiddleware: Middleware = {
  async onRequest({ request }) {
    const token = await auth.currentUser?.getIdToken();
    if (token) request.headers.set("Authorization", `Bearer ${token}`);
    return request;
  },
  async onResponse({ response }) {
    if (response.status === 401 && auth.currentUser) await auth.signOut();
    return response;
  },
};

api.use(authMiddleware);
